                            emon.Port.CellsSet(stk, (sp * 2) + 1, bi);
                            emon.Port.CellsSet(stk, (sp * 2) + 2, bi);
                            emon.Port.CellsSet(stk, (sp * 2) + 3, b);
                            sp += 2;
                        }
                    } else if ((best * ((long) 4)) > ((long) e2)) {
                        emon.Port.CellsSet(keep, TrPtWrap(bi, m), 1);
                        emon.Port.CellsSet(stk, sp * 2, a);
                        emon.Port.CellsSet(stk, (sp * 2) + 1, bi);
                        emon.Port.CellsSet(stk, (sp * 2) + 2, bi);
                        emon.Port.CellsSet(stk, (sp * 2) + 3, b);
                        sp += 2;
                    }
                }
            }
        }
        i = 0;
        while (i < m) {
            kept += emon.Port.CellsAt(keep, i);
            i += 1;
        }
        return kept;
    }
    public static int TrSortKeys(emon.Port.Cells keys, int n, emon.Port.Cells idx, emon.Port.Cells tmp) {
        // `idx` (n cells, 0 1 2 ... in) sorted by `keys[idx]`, ties by the index: a bottom-up merge sort. `tmp` is scratch.
        int width = 1;
        int lo = 0;
        int mid = 0;
        int hi = 0;
        int i = 0;
        int j = 0;
        int k = 0;
        int ai = 0;
        int bj = 0;
        int ka = 0;
        int kb = 0;
        emon.Port.CellsDrop(tmp, 0);
        emon.Port.CellsGrow(tmp, n, 0);
        while (width < n) {
            lo = 0;
            while (lo < n) {
                mid = TrMin(lo + width, n);
                hi = TrMin(lo + (2 * width), n);
                i = lo;
                j = mid;
                k = lo;
                while ((i < mid) && (j < hi)) {
                    ai = emon.Port.CellsAt(idx, i);
                    bj = emon.Port.CellsAt(idx, j);
                    ka = emon.Port.CellsAt(keys, ai);
                    kb = emon.Port.CellsAt(keys, bj);
                    if (kb < ka) {
                        emon.Port.CellsSet(tmp, k, bj);
                        j += 1;
                    } else {
                        emon.Port.CellsSet(tmp, k, ai);
                        i += 1;
                    }
                    k += 1;
                }
                while (i < mid) {
                    emon.Port.CellsSet(tmp, k, emon.Port.CellsAt(idx, i));
                    i += 1;
                    k += 1;
                }
                while (j < hi) {
                    emon.Port.CellsSet(tmp, k, emon.Port.CellsAt(idx, j));
                    j += 1;
                    k += 1;
                }
                lo = hi;
            }
            k = 0;
            while (k < n) {
                emon.Port.CellsSet(idx, k, emon.Port.CellsAt(tmp, k));
                k += 1;
            }
            width *= 2;
        }
        return 0;
    }
    public static int TrH2cpt(emon.Port.Cells views, int view, int axis, int x2, int y2) {
        // Page space (centipoints, one axis) of the HALF-PIXEL position (x2 / 2, y2 / 2) of a view: the mean of the mapped pixel
        // corners around it (a position on the grid is one corner, on an edge two, in a pixel's centre four).
        int x0 = (x2) >> (1);
        int y0 = (y2) >> (1);
        int xo = x2 & 1;
        int yo = y2 & 1;
        int s = Evidence.VwPxToCpt(views, view, axis, x0, y0);
        int n = 1;
        if (xo == 1) {
            s += Evidence.VwPxToCpt(views, view, axis, x0 + 1, y0);
            n += 1;
        }
        if (yo == 1) {
            s += Evidence.VwPxToCpt(views, view, axis, x0, y0 + 1);
            n += 1;
        }
        if ((xo == 1) && (yo == 1)) {
            s += Evidence.VwPxToCpt(views, view, axis, x0 + 1, y0 + 1);
            n += 1;
        }
        if (n == 1) {
            return s;
        }
        return ((s * 2) + n) / (2 * n);
    }
