    internal const int PX0 = 0;
    internal const int PY0 = 1;
    internal const int PX1 = 2;
    internal const int PY1 = 3;
    internal const int PThk = 4;
    internal const int PComp = 5;
    internal const int POri = 6;
    internal const int PMinw = 7;
    internal const int PMaxw = 8;
