    public static int TrMaxPieces() {
        // Rule pieces kept for one page (the merge compares pairs).
        return 6000;
    }
    internal static int TrEligible(emon.Port.Cells cs, int comp) {
        // 1 when rules may be found in component `comp`: it is neither noise nor a glyph.
        if (comp < 0) {
            return 0;
        }
        if (TrCg(cs, comp, CKind) == TrKNoise()) {
            return 0;
        }
        if (TrCg(cs, comp, CKind) == TrKText()) {
            return 0;
        }
        return 1;
    }
    public static int TrSlicesRows(emon.Port.Cells rn, emon.Port.Cells ri, int h, emon.Port.Cells cs, int thick, emon.Port.Cells sl) {
        // The row runs that may belong to a vertical rule, as slices [y x0 x1 comp]: thin (at most `thick` pixels) runs of
        // components that are neither noise nor glyphs. Answers how many.
        int n = emon.Port.CellsAt(ri, h);
        int r = 0;
        int ns = 0;
        int c = 0;
        emon.Port.CellsDrop(sl, 0);
        while (r < n) {
            c = TrRg(rn, r, 5);
            if ((TrRg(rn, r, 2) - TrRg(rn, r, 1)) <= thick) {
                if (TrEligible(cs, c) == 1) {
                    emon.Port.CellsPush(sl, TrRg(rn, r, 0));
                    emon.Port.CellsPush(sl, TrRg(rn, r, 1));
                    emon.Port.CellsPush(sl, TrRg(rn, r, 2));
                    emon.Port.CellsPush(sl, c);
                    ns += 1;
                }
            }
            r += 1;
        }
        return ns;
    }
    public static int TrSlicesCols(emon.Port.Cells vr, int nv, int w, emon.Port.Cells cs, int thick, emon.Port.Cells sl, emon.Port.Cells idx, emon.Port.Cells off) {
        // The column runs that may belong to a horizontal rule, as slices [x y0 y1 comp] in order of x then y0: the thin column
        // runs of components that are neither noise nor glyphs, grouped by column (a counting sort). Answers how many.
        int x = 0;
        int k = 0;
        int v = 0;
        int ns = 0;
        int lo = 0;
        int hi = 0;
        TrGroup(vr, 4, 1, nv, w, idx, off);
        emon.Port.CellsDrop(sl, 0);
        while (x < w) {
            lo = emon.Port.CellsAt(off, x);
            hi = emon.Port.CellsAt(off, x + 1);
            k = lo;
            while (k < hi) {
                v = emon.Port.CellsAt(idx, k);
                if ((emon.Port.CellsAt(vr, (v * 4) + 3) - emon.Port.CellsAt(vr, (v * 4) + 2)) <= thick) {
                    if (TrEligible(cs, emon.Port.CellsAt(vr, v * 4)) == 1) {
                        emon.Port.CellsPush(sl, x);
                        emon.Port.CellsPush(sl, emon.Port.CellsAt(vr, (v * 4) + 2));
                        emon.Port.CellsPush(sl, emon.Port.CellsAt(vr, (v * 4) + 3));
                        emon.Port.CellsPush(sl, emon.Port.CellsAt(vr, v * 4));
                        ns += 1;
                    }
                }
                k += 1;
            }
            x += 1;
        }
        return ns;
    }
    internal static int TrLinkSlices(emon.Port.Cells sl, int ns, emon.Port.Cells lk) {
        // Chain the slices: a slice joins one of the previous major coordinate's (consecutive row or column) whose two edges are
        // both within one pixel of its own, each slice having at most one successor. `lk` gets [pred succ] per slice (-1 none).
        int i = 0;
        int j = 0;
        int m = 0;
        int pg0 = 0;
        int pg1 = 0;
        int pm = -100;
        int s = 0;
        int pp = 0;
        int q = 0;
        int lo = 0;
        int hi = 0;
        int nl = 0;
        emon.Port.CellsDrop(lk, 0);
        emon.Port.CellsGrow(lk, ns * 2, -1);
        while (i < ns) {
            m = emon.Port.CellsAt(sl, i * 4);
            j = i;
            while ((j < ns) && (emon.Port.CellsAt(sl, j * 4) == m)) {
                j += 1;
            }
            if (pm == (m - 1)) {
                pp = pg0;
                s = i;
                while (s < j) {
                    lo = emon.Port.CellsAt(sl, (s * 4) + 1);
                    hi = emon.Port.CellsAt(sl, (s * 4) + 2);
                    while ((pp < pg1) && (emon.Port.CellsAt(sl, (pp * 4) + 1) < (lo - 1))) {
                        pp += 1;
                    }
                    q = pp;
                    while ((q < pg1) && (emon.Port.CellsAt(sl, (q * 4) + 1) <= (lo + 1))) {
                        if ((TrAbs(emon.Port.CellsAt(sl, (q * 4) + 2) - hi) <= 1) && (emon.Port.CellsAt(lk, (q * 2) + 1) == -1)) {
                            emon.Port.CellsSet(lk, s * 2, q);
                            emon.Port.CellsSet(lk, (q * 2) + 1, s);
                            nl += 1;
                            q = pg1;
                        } else {
                            q += 1;
                        }
                    }
                    s += 1;
                }
            }
            pg0 = i;
            pg1 = j;
            pm = m;
            i = j;
        }
        return nl;
    }
    public static int TrChains(emon.Port.Cells sl, int ns, int ori, int pmin, emon.Port.Cells cs, emon.Port.Cells pc, int maxp, emon.Port.Cells lk, emon.Port.Cells buf, emon.Port.Cells chn, emon.Port.Cells keep, emon.Port.Cells stk) {
        // Chains of slices (`tr-link-slices`) straightened by Douglas-Peucker into PIECES appended to `pc` (stride 12, doubled
        // pixels: x0 y0 x1 y1, thickness x4, component, orientation `ori`, narrowest and widest slice, slices). `ori` 0: the major
        // coordinate is x (slices are columns, a horizontal-ish rule), 1: it is y (rows, a vertical-ish one). A chain shorter than
        // `pmin` is dropped; one that is not straight (its longest straight stretch under 4/5 of it) is dropped; else the stretch is
        // the piece. Answers the number of pieces in `pc` afterwards.
        int s = 0;
        int t = 0;
        int mc = 0;
        int a = 0;
        int b = 0;
        int la = 0;
        int lb = 0;
        int lbest = 0;
        int prev = -1;
        int k = 0;
        int lo = 0;
        int hi = 0;
        int m = 0;
        int np = emon.Port.CellsLen(pc) / 12;
        int sw = 0;
        int minw = 0;
        int maxw = 0;
        int majs = 0;
        int majb = 0;
        int mina = 0;
        int minb = 0;
        int w = 0;
        int kn = 0;
        TrLinkSlices(sl, ns, lk);
        s = 0;
        while (s < ns) {
            if (emon.Port.CellsAt(lk, s * 2) == -1) {
                emon.Port.CellsDrop(chn, 0);
                emon.Port.CellsDrop(buf, 0);
                t = s;
                mc = 0;
                while (t >= 0) {
                    emon.Port.CellsPush(chn, t);
                    m = emon.Port.CellsAt(sl, t * 4);
                    lo = emon.Port.CellsAt(sl, (t * 4) + 1);
                    hi = emon.Port.CellsAt(sl, (t * 4) + 2);
                    if (ori == 0) {
                        emon.Port.CellsPush(buf, m);
                        emon.Port.CellsPush(buf, (lo + hi) / 2);
                    } else {
                        emon.Port.CellsPush(buf, (lo + hi) / 2);
                        emon.Port.CellsPush(buf, m);
                    }
                    mc += 1;
                    t = emon.Port.CellsAt(lk, (t * 2) + 1);
                }
                if (mc >= pmin) {
                    if (np < maxp) {
                        TrSimplify(buf, mc, 0, TrDpEps2(), keep, stk);
                        lbest = 0;
                        la = 0;
                        lb = 0;
                        prev = 0;
                        k = 1;
                        while (k < mc) {
                            if (emon.Port.CellsAt(keep, k) == 1) {
                                if ((k - prev) > lbest) {
                                    lbest = k - prev;
                                    la = prev;
                                    lb = k;
                                }
                                prev = k;
                            }
                            k += 1;
                        }
                        if (((lbest + 1) * 5) >= (mc * 4)) {
                            sw = 0;
                            minw = 100000;
                            maxw = 0;
                            k = la;
                            while (k <= lb) {
                                t = emon.Port.CellsAt(chn, k);
                                w = emon.Port.CellsAt(sl, (t * 4) + 2) - emon.Port.CellsAt(sl, (t * 4) + 1);
                                sw += w;
                                if (w < minw) {
                                    minw = w;
                                }
                                if (w > maxw) {
                                    maxw = w;
                                }
                                k += 1;
                            }
                            kn = (lb - la) + 1;
                            a = emon.Port.CellsAt(chn, la);
                            b = emon.Port.CellsAt(chn, lb);
                            majs = 2 * emon.Port.CellsAt(sl, a * 4);
                            if (la > 0) {
                                majs += 1;
                            }
                            majb = 2 * (emon.Port.CellsAt(sl, b * 4) + 1);
                            if (lb < (mc - 1)) {
                                majb -= 1;
                            }
                            mina = emon.Port.CellsAt(sl, (a * 4) + 1) + emon.Port.CellsAt(sl, (a * 4) + 2);
                            minb = emon.Port.CellsAt(sl, (b * 4) + 1) + emon.Port.CellsAt(sl, (b * 4) + 2);
                            if (ori == 0) {
                                emon.Port.CellsPush(pc, majs);
                                emon.Port.CellsPush(pc, mina);
                                emon.Port.CellsPush(pc, majb);
                                emon.Port.CellsPush(pc, minb);
                            } else {
                                emon.Port.CellsPush(pc, mina);
                                emon.Port.CellsPush(pc, majs);
                                emon.Port.CellsPush(pc, minb);
                                emon.Port.CellsPush(pc, majb);
                            }
                            emon.Port.CellsPush(pc, ((sw * 4) + (kn / 2)) / kn);
                            emon.Port.CellsPush(pc, emon.Port.CellsAt(sl, (a * 4) + 3));
                            emon.Port.CellsPush(pc, ori);
                            emon.Port.CellsPush(pc, minw);
                            emon.Port.CellsPush(pc, maxw);
                            emon.Port.CellsPush(pc, kn);
                            emon.Port.CellsPush(pc, np);
                            emon.Port.CellsPush(pc, 0);
                            np += 1;
                        }
                    }
                }
            }
            s += 1;
        }
        return np;
    }
    internal static int TrSameLine(emon.Port.Cells pc, int a, int b, int gapmax) {
        // 1 when pieces a and b lie on one straight line and are at most `gapmax` (doubled pixels) apart along it: the angle between
        // them under 2.5 degrees, both ends of the shorter within (thickness + 2 px) of the longer one's line.
        int p = a;
        int q = b;
        int pdx0 = emon.Port.CellsAt(pc, (a * Ps) + PX1) - emon.Port.CellsAt(pc, (a * Ps) + PX0);
        int pdy0 = emon.Port.CellsAt(pc, (a * Ps) + PY1) - emon.Port.CellsAt(pc, (a * Ps) + PY0);
        int qdx0 = emon.Port.CellsAt(pc, (b * Ps) + PX1) - emon.Port.CellsAt(pc, (b * Ps) + PX0);
        int qdy0 = emon.Port.CellsAt(pc, (b * Ps) + PY1) - emon.Port.CellsAt(pc, (b * Ps) + PY0);
        long l1 = unchecked(((long) pdx0) * ((long) pdx0)) + unchecked(((long) pdy0) * ((long) pdy0));
        long l2 = unchecked(((long) qdx0) * ((long) qdx0)) + unchecked(((long) qdy0) * ((long) qdy0));
        if (l1 < l2) {
            p = b;
            q = a;
        }
        int px0 = emon.Port.CellsAt(pc, (p * Ps) + PX0);
        int py0 = emon.Port.CellsAt(pc, (p * Ps) + PY0);
        int dx = emon.Port.CellsAt(pc, (p * Ps) + PX1) - px0;
        int dy = emon.Port.CellsAt(pc, (p * Ps) + PY1) - py0;
        int ex = emon.Port.CellsAt(pc, (q * Ps) + PX1) - emon.Port.CellsAt(pc, (q * Ps) + PX0);
        int ey = emon.Port.CellsAt(pc, (q * Ps) + PY1) - emon.Port.CellsAt(pc, (q * Ps) + PY0);
        long lp2 = unchecked(((long) dx) * ((long) dx)) + unchecked(((long) dy) * ((long) dy));
        long lq2 = unchecked(((long) ex) * ((long) ex)) + unchecked(((long) ey) * ((long) ey));
        long cr = unchecked(((long) dx) * ((long) ey)) - unchecked(((long) dy) * ((long) ex));
        int lp = TrIsqrt(lp2);
        int tol = (TrMax(emon.Port.CellsAt(pc, (p * Ps) + PThk), emon.Port.CellsAt(pc, (q * Ps) + PThk)) / 4) + 4;
        int qx0 = emon.Port.CellsAt(pc, (q * Ps) + PX0) - px0;
        int qy0 = emon.Port.CellsAt(pc, (q * Ps) + PY0) - py0;
        int qx1 = emon.Port.CellsAt(pc, (q * Ps) + PX1) - px0;
        int qy1 = emon.Port.CellsAt(pc, (q * Ps) + PY1) - py0;
        long c0 = unchecked(((long) dx) * ((long) qy0)) - unchecked(((long) dy) * ((long) qx0));
        long c1 = unchecked(((long) dx) * ((long) qy1)) - unchecked(((long) dy) * ((long) qx1));
        long d0 = unchecked(((long) dx) * ((long) qx0)) + unchecked(((long) dy) * ((long) qy0));
        long d1 = unchecked(((long) dx) * ((long) qx1)) + unchecked(((long) dy) * ((long) qy1));
        long t0 = 0;
        long t1 = 0;
        long ad = 0;
        if (lp <= 0) {
            return 0;
        }
        if ((cr * cr) > (unchecked(lp2 * lq2) / ((long) 526))) {
            return 0;
        }
        ad = c0;
        if (ad < ((long) 0)) {
            ad = ((long) 0) - ad;
        }
        if (ad > unchecked(((long) tol) * ((long) lp))) {
            return 0;
        }
        ad = c1;
        if (ad < ((long) 0)) {
            ad = ((long) 0) - ad;
        }
        if (ad > unchecked(((long) tol) * ((long) lp))) {
            return 0;
        }
        // along the line: t = dot / |d|, the longer piece spanning 0 .. lp
        t0 = d0 / ((long) lp);
        t1 = d1 / ((long) lp);
        if (t1 < t0) {
            ad = t0;
            t0 = t1;
            t1 = ad;
        }
        if ((t0 - ((long) lp)) > ((long) gapmax)) {
            return 0;
        }
        if ((((long) 0) - t1) > ((long) gapmax)) {
            return 0;
        }
        return 1;
    }
    internal static int TrPfind(emon.Port.Cells pc, int a) {
        int x = a;
        int p = 0;
        int g = 0;
        p = emon.Port.CellsAt(pc, (x * Ps) + PPar);
        while (p != x) {
            g = emon.Port.CellsAt(pc, (p * Ps) + PPar);
            emon.Port.CellsSet(pc, (x * Ps) + PPar, g);
            x = g;
            p = emon.Port.CellsAt(pc, (x * Ps) + PPar);
        }
        return x;
    }
    public static int TrMergePieces(emon.Port.Cells pc, int np, int gapmax, emon.Port.Cells keys, emon.Port.Cells ord, emon.Port.Cells tmp) {
        // Union the pieces that lie on one line and are within `gapmax` doubled pixels along it (`tr-same-line`): every piece's
        // PARENT cell ends up its group's root (the smallest index). Pieces are visited by their left edge so that a pair is only
        // compared while their x-ranges can still meet. Answers the number of groups.
        int i = 0;
        int j = 0;
        int p = 0;
        int q = 0;
        int pmax = 0;
        int ra = 0;
        int rb = 0;
        int ng = 0;
        emon.Port.CellsDrop(keys, 0);
        emon.Port.CellsDrop(ord, 0);
        i = 0;
        while (i < np) {
            emon.Port.CellsSet(pc, (i * Ps) + PPar, i);
            emon.Port.CellsPush(keys, TrMin(emon.Port.CellsAt(pc, (i * Ps) + PX0), emon.Port.CellsAt(pc, (i * Ps) + PX1)));
            emon.Port.CellsPush(ord, i);
            i += 1;
        }
        TrSortKeys(keys, np, ord, tmp);
        i = 0;
        while (i < np) {
            p = emon.Port.CellsAt(ord, i);
            pmax = TrMax(emon.Port.CellsAt(pc, (p * Ps) + PX0), emon.Port.CellsAt(pc, (p * Ps) + PX1)) + gapmax;
            j = i + 1;
            while ((j < np) && (emon.Port.CellsAt(keys, emon.Port.CellsAt(ord, j)) <= pmax)) {
                q = emon.Port.CellsAt(ord, j);
                if (TrSameLine(pc, p, q, gapmax) == 1) {
                    ra = TrPfind(pc, p);
                    rb = TrPfind(pc, q);
                    if (ra != rb) {
                        if (ra < rb) {
                            emon.Port.CellsSet(pc, (rb * Ps) + PPar, ra);
                        } else {
                            emon.Port.CellsSet(pc, (ra * Ps) + PPar, rb);
                        }
                    }
                }
                j += 1;
            }
            i += 1;
        }
        i = 0;
        while (i < np) {
            emon.Port.CellsSet(pc, (i * Ps) + PPar, TrPfind(pc, i));
            if (emon.Port.CellsAt(pc, (i * Ps) + PPar) == i) {
                ng += 1;
            }
            i += 1;
        }
        return ng;
    }
