    internal static int TrSegAddMember(emon.Port.Cells mem, int mfirst, int comp) {
        // Append `comp` to the member list from `mfirst` unless it is already there. Answers 1 when it was added.
        int n = emon.Port.CellsLen(mem);
        int i = mfirst;
        while (i < n) {
            if (emon.Port.CellsAt(mem, i) == comp) {
                return 0;
            }
            i += 1;
        }
        emon.Port.CellsPush(mem, comp);
        return 1;
    }
    public static int TrSegments(emon.Port.Cells pc, int np, int rmin, emon.Port.Cells sg, emon.Port.Cells mem, emon.Port.Cells idx, emon.Port.Cells off, emon.Port.Cells tmp) {
        // One SEGMENT per group of pieces (their PARENT cell, from `tr-merge-pieces`): the longest piece's line, the endpoints the
        // extreme points along it, the thickness the length-weighted mean, the total gap between the pieces along the line, the member
        // components in `mem`. Groups shorter than `rmin` pixels are kept too (`tr-dashes` may join them). Answers the segments.
        int g = 0;
        int k = 0;
        int lo = 0;
        int hi = 0;
        int p = 0;
        int rf = 0;
        long rl2 = 0;
        long l2 = 0;
        int dx = 0;
        int dy = 0;
        int lr = 0;
        long tmin = 0;
        long tmax = 0;
        long t = 0;
        int amin = 0;
        int amax = 0;
        long sthk = 0;
        long slen = 0;
        int minw = 0;
        int maxw = 0;
        int mf = 0;
        int ns = 0;
        int j = 0;
        int cnt = 0;
        int e = 0;
        int x = 0;
        int y = 0;
        long gaps = 0;
        long cur = 0;
        long ta = 0;
        long tb = 0;
