    internal static int TrSortedMedian(emon.Port.Cells a, int n) {
        // Sort a[0..n) in place (insertion) and answer its upper median a[n / 2]; 0 for none.
        int i = 1;
        int j = 0;
        int v = 0;
        if (n <= 0) {
            return 0;
