                                off = ((long) 0) - off;
                            }
                            thk = TrMax(emon.Port.CellsAt(sg, (i * Sg) + GThk), emon.Port.CellsAt(sg, (j * Sg) + GThk));
                            // thk is x4 pixels, so doubled pixels are thk / 2: between 1 and 3 thicknesses
                            if (((off * ((long) 2)) >= ((long) thk)) && ((off * ((long) 2)) <= (((long) thk) * ((long) 3)))) {
                                // overlap along i's axis of j's extent with i's
                                t0 = (unchecked(((long) (emon.Port.CellsAt(sg, (j * Sg) + GAx) - emon.Port.CellsAt(sg, (i * Sg) + GAx))) * ((long) dx)) + unchecked(((long) (emon.Port.CellsAt(sg, (j * Sg) + GAy) - emon.Port.CellsAt(sg, (i * Sg) + GAy))) * ((long) dy))) / ((long) li);
                                t1 = (unchecked(((long) (emon.Port.CellsAt(sg, (j * Sg) + GBx) - emon.Port.CellsAt(sg, (i * Sg) + GAx))) * ((long) dx)) + unchecked(((long) (emon.Port.CellsAt(sg, (j * Sg) + GBy) - emon.Port.CellsAt(sg, (i * Sg) + GAy))) * ((long) dy))) / ((long) li);
                                if (t1 < t0) {
                                    ov = t0;
                                    t0 = t1;
                                    t1 = ov;
                                }
                                if (t0 < ((long) 0)) {
                                    t0 = (long) 0;
                                }
                                if (t1 > ((long) li)) {
                                    t1 = (long) li;
                                }
                                ov = t1 - t0;
                                small = (long) TrMin(li, TrIsqrt(l2));
                                if ((ov > ((long) 0)) && ((ov * ((long) 10)) >= (small * ((long) 6)))) {
                                    emon.Port.CellsSet(sg, (i * Sg) + GStyle, 4);
                                    emon.Port.CellsSet(sg, (j * Sg) + GStyle, 4);
                                    n += 1;
                                }
                            }
                        }
                    }
                    j += 1;
                }
            }
            i += 1;
        }
        return n;
    }
    public static int TrRuleRows(emon.Port.Cells views, int page, int view, int dpi100, emon.Port.Cells cs, emon.Port.Cells sg, int ns, emon.Port.Cells mem, emon.Port.Cells inks, emon.Port.Cells rules, emon.Port.Cells refs, emon.Port.Cells comps) {
        // Write one `rules` row (SPEC 8.4.4) for every segment whose style is not 0: the box through the view, the centre-line
        // endpoints (half pixels mapped), thickness, the colour and ink row of its first member's layer, the style, a confidence
        // (1000 minus the per-mille of its length that is gap, dashes excepted, minus 300 when its thickness varies by more than half
        // along it; never below 0, D226) and its member components as `refs`. Each member's `C_RULE` is the row. Answers the rows.
        int i = 0;
        int rows = 0;
        int r = 0;
        int ax = 0;
        int ay = 0;
        int bx = 0;
        int by = 0;
        int thkpx = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        int style = 0;
        int conf = 0;
        int k = 0;
        int c = 0;
        int ir = 0;
        int rf = 0;
        int thk = 0;
        int ln = 0;
        while (i < ns) {
            style = emon.Port.CellsAt(sg, (i * Sg) + GStyle);
            if (style > 0) {
                ax = emon.Port.CellsAt(sg, (i * Sg) + GAx);
                ay = emon.Port.CellsAt(sg, (i * Sg) + GAy);
                bx = emon.Port.CellsAt(sg, (i * Sg) + GBx);
                by = emon.Port.CellsAt(sg, (i * Sg) + GBy);
                thk = emon.Port.CellsAt(sg, (i * Sg) + GThk);
                thkpx = (thk + 3) / 4;
                x0 = (TrMin(ax, bx) - thkpx) >> (1);
                y0 = (TrMin(ay, by) - thkpx) >> (1);
                x1 = ((TrMax(ax, bx) + thkpx) + 1) >> (1);
                y1 = ((TrMax(ay, by) + thkpx) + 1) >> (1);
                r = Evidence.RlNew(rules, page, Evidence.VwBoxToCpt(views, view, 0, x0, y0, x1 - x0, y1 - y0), Evidence.VwBoxToCpt(views, view, 1, x0, y0, x1 - x0, y1 - y0), Evidence.VwBoxToCpt(views, view, 2, x0, y0, x1 - x0, y1 - y0), Evidence.VwBoxToCpt(views, view, 3, x0, y0, x1 - x0, y1 - y0), view);
                Evidence.RlSet(rules, r, Evidence.RlfLx0(), TrH2cpt(views, view, 0, ax, ay));
                Evidence.RlSet(rules, r, Evidence.RlfLy0(), TrH2cpt(views, view, 1, ax, ay));
                Evidence.RlSet(rules, r, Evidence.RlfLx1(), TrH2cpt(views, view, 0, bx, by));
                Evidence.RlSet(rules, r, Evidence.RlfLy1(), TrH2cpt(views, view, 1, bx, by));
                Evidence.RlSet(rules, r, Evidence.RlfThick(), TrLenCpt(thk, dpi100 * 4));
                c = emon.Port.CellsAt(sg, (i * Sg) + GComp);
                ir = TrCg(cs, c, CInkrow);
                Evidence.RlSet(rules, r, Evidence.RlfInk(), ir);
                if (ir >= 0) {
                    Evidence.RlSet(rules, r, Evidence.RlfColor(), Evidence.IkGet(inks, ir, Evidence.IkfColor()));
                }
                if (style == 2) {
                    Evidence.RlSet(rules, r, Evidence.RlfStyle(), Evidence.RsDashed());
                }
                if (style == 3) {
                    Evidence.RlSet(rules, r, Evidence.RlfStyle(), Evidence.RsDotted());
                }
                if (style == 4) {
                    Evidence.RlSet(rules, r, Evidence.RlfStyle(), Evidence.RsDouble());
                }
                if (style <= 1) {
                    Evidence.RlSet(rules, r, Evidence.RlfStyle(), Evidence.RsSolid());
                }
                // confidence
                ln = emon.Port.CellsAt(sg, (i * Sg) + GLen);
                conf = 1000;
                if ((style == 1) || (style == 4)) {
                    conf -= TrPermille(emon.Port.CellsAt(sg, (i * Sg) + GGaps), TrMax(1, ln));
                }
                if ((2 * ((emon.Port.CellsAt(sg, (i * Sg) + GMaxw) - emon.Port.CellsAt(sg, (i * Sg) + GMinw)) - 1)) > ((thk + 2) / 4)) {
                    conf -= 300;
                }
                if (conf < 0) {
                    conf = 0;
                }
                Evidence.RlSet(rules, r, Evidence.RlfConf(), conf);
                // members
                Evidence.RlSet(rules, r, Evidence.RlfRfirst(), emon.Port.CellsLen(refs) / 2);
                Evidence.RlSet(rules, r, Evidence.RlfRcount(), emon.Port.CellsAt(sg, (i * Sg) + GMcount));
                k = 0;
                while (k < emon.Port.CellsAt(sg, (i * Sg) + GMcount)) {
                    c = emon.Port.CellsAt(mem, emon.Port.CellsAt(sg, (i * Sg) + GMfirst) + k);
                    emon.Port.CellsPush(refs, Evidence.EaComponents());
                    emon.Port.CellsPush(refs, TrCg(cs, c, CEvrow));
                    if (TrCg(cs, c, CRule) < 0) {
                        TrCset(cs, c, CRule, r);
                    }
                    k += 1;
                }
                rows += 1;
            }
            i += 1;
        }
        return rows;
    }
    public static int TrRules(emon.Port.Cells views, int page, int view, int dpi100, int w, int h, emon.Port.Cells rn, emon.Port.Cells ri, emon.Port.Cells cs, emon.Port.Cells vr, int nv, emon.Port.Cells comps, emon.Port.Cells rules, emon.Port.Cells refs, emon.Port.Cells inks, emon.Port.Cells pc, emon.Port.Cells sg, emon.Port.Cells mem, emon.Port.Cells s1, emon.Port.Cells s2, emon.Port.Cells s3, emon.Port.Cells s4, emon.Port.Cells s5, emon.Port.Cells s6) {
        // Rules (SPEC 8.2, D226): stacks of short row runs (vertical and steep rules) and of short column runs (horizontal and
        // shallow ones) inside every component that is neither noise nor a glyph, chained, straightened, merged along their axis
        // within `tr-rule-gap`, joined into dashed and dotted rules, doubles marked, written as `rules` rows. A rule-like component
        // (`tr-kinds`) that gave no rule becomes large (its `components` row says `blob`). Answers the number of rule rows.
        int thick = TrRuleThick(dpi100);
        int rmin = TrRuleMin(dpi100);
        int gap = TrRuleGap(dpi100);
        int pmin = TrMax(6, rmin / 3);
        int maxp = TrMaxPieces();
        int ns = 0;
        int np = 0;
        int nseg = 0;
        int rows = 0;
        int c = 0;
        int er = 0;
        int nc = emon.Port.CellsLen(cs) / 24;
        emon.Port.CellsDrop(pc, 0);
        ns = TrSlicesRows(rn, ri, h, cs, thick, s1);
        np = TrChains(s1, ns, 1, pmin, cs, pc, maxp, s2, s3, s4, s5, s6);
        ns = TrSlicesCols(vr, nv, w, cs, thick, s1, s2, s3);
        np = TrChains(s1, ns, 0, pmin, cs, pc, maxp, s2, s3, s4, s5, s6);
        if (np > 0) {
            TrMergePieces(pc, np, gap * 2, s1, s2, s3);
            nseg = TrSegments(pc, np, rmin, sg, mem, s1, s2, s3);
            TrDashes(sg, nseg, rmin, TrPt(dpi100, 6) * 2, mem, pc, s1, s2, s3, s4);
            TrDoubles(sg, nseg);
            rows = TrRuleRows(views, page, view, dpi100, cs, sg, nseg, mem, inks, rules, refs, comps);
        }
        c = 0;
        while (c < nc) {
            if (TrCg(cs, c, CKind) == TrKRule()) {
                if (TrCg(cs, c, CRule) < 0) {
                    TrCset(cs, c, CKind, TrKLarge());
                    er = TrCg(cs, c, CEvrow);
                    if (er >= 0) {
                        Evidence.CoSet(comps, er, Evidence.CfKind(), Evidence.CkBlob());
                        Evidence.CoSet(comps, er, Evidence.CfConf(), TrConfOf(TrKLarge()));
                    }
                }
            }
            c += 1;
        }
        return rows;
    }
}
